preConditionHook:
// FILTER: price has travelled at least scalpDistance beyond the breakout
// level within the first few bars after the breakout, with no pullback
// through that level -- read the move as new with-trend buying rather than a
// reversal setup.
//
// Kept apart from SpikeWithoutPullback on purpose: this measures distance
// from a SPECIFIC breakout level inside a fixed window after it, where
// SpikeWithoutPullback is a rolling window statistic with no level at all.
//
// The breakout bar is the most recent bar k in 0..confirmBars -- the current
// bar included, so the filter is live on the breakout bar itself -- whose
// close is beyond the extreme of the breakoutLookback bars ending one bar
// before it. The level is open-coded because a function-history reference at
// a VARIABLE offset is not available; Extremes(), which Highest and Lowest
// call, is EL source and is exactly this loop, so the comparisons carry the
// relational tolerance and go through el_gt / el_lt. "Most recent" is the
// brkUpBar == -1 guard rather than a loop break, because EasyLanguage has
// none and the twins must run the same iterations.
//
// "No pullback" is the lowest low of the bars from the breakout bar to now,
// bars 0..brkUpBar, holding at or above the level -- since the breakout, not
// over a fixed window that would reach back before it.
//
// scalpDistance is in PRICE POINTS, as BreakoutMissesScalpTarget's is: the
// source states it in ticks and the engine exposes no tick size to strategies
// (MinMove / PriceScale are measured but not reachable here), so the
// threshold is instrument-specific and must be set per symbol in the grid.
//
// The deepest bar touched is confirmBars + breakoutLookback.
brkUpBar = -1;
brkDnBar = -1;
lvlUpAt = 0.0;
lvlDnAt = 0.0;
for (int k = 0; k <= (int)confirmBars; ++k) {
    double lvlHigh = high[k + 1];
    double lvlLow = low[k + 1];
    for (int j = k + 2; j <= k + (int)breakoutLookback; ++j) {
        if (el_gt(high[j], lvlHigh)) lvlHigh = high[j];
        if (el_lt(low[j], lvlLow)) lvlLow = low[j];
    }
    if (brkUpBar == -1 && el_gt(close[k], lvlHigh)) { brkUpBar = k; lvlUpAt = lvlHigh; }
    if (brkDnBar == -1 && el_lt(close[k], lvlLow)) { brkDnBar = k; lvlDnAt = lvlLow; }
}
minLowSince = low[0];
maxHighSince = high[0];
if (brkUpBar != -1) {
    for (int m = 1; m <= brkUpBar; ++m) {
        if (el_lt(low[m], minLowSince)) minLowSince = low[m];
    }
}
if (brkDnBar != -1) {
    for (int m = 1; m <= brkDnBar; ++m) {
        if (el_gt(high[m], maxHighSince)) maxHighSince = high[m];
    }
}
runUp = brkUpBar != -1 && el_ge(close[0] - lvlUpAt, scalpDistance) && el_ge(minLowSince, lvlUpAt);
runDn = brkDnBar != -1 && el_ge(lvlDnAt - close[0], scalpDistance) && el_le(maxHighSince, lvlDnAt);
